import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame} from 'remotion';
import scenes from '../public/scenes.json';
import storySvg from '../public/story.svg';

// The storyboard is generated by the Python agent: public/story.svg
// (all panels, art, embedded media) + public/scenes.json (title, panel
// count, dimensions AND video options: resolution, fps, camera style,
// theme, outro text). Both are webpack modules, so editing them
// invalidates the bundle cache and re-rendering picks up the change.

// Panel layout (must match video_agent/storyboard.py):
//   panel i spans x = 50 + 1200*i .. 1200*(i+1), y = 760 .. 1400
const PANEL_LEFT = 50;
const PANEL_STEP = 1200;
const PANEL_CENTER_Y = 1080;

// Reference framing is designed for 1080p; scale everything by the
// actual output width so 720p/1080p/2160p all frame identically.
const REF_W = 1920;
const K = scenes.video_w / REF_W;

const BASE_SCALE = 1.55;
const PEAK_SCALE = 1.62;

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

const cameraAt = (frame: number): {x: number; y: number; scale: number} => {
  const seg = Math.min(
    Math.floor(frame / scenes.scene_frames),
    scenes.scene_count - 1
  );
  const t = (frame - seg * scenes.scene_frames) / scenes.scene_frames;
  const e = Easing.inOut(Easing.cubic)(t);
  const x0 = PANEL_LEFT + seg * PANEL_STEP - 20;
  const yCenter = PANEL_CENTER_Y - 540 / BASE_SCALE;
  const style = scenes.camera_style ?? 'pan';

  if (style === 'static') {
    return {x: x0 + 40, y: yCenter, scale: BASE_SCALE};
  }
  if (style === 'zoom') {
    return {x: x0 + 40, y: yCenter, scale: lerp(1.4, 1.72, e)};
  }
  // pan: drift right + gentle scale, alternating y for life
  const driftY = seg % 2 === 0 ? -20 : 20;
  return {
    x: lerp(x0, x0 + 40, e),
    y: lerp(yCenter + driftY, yCenter - driftY, e),
    scale: lerp(BASE_SCALE, PEAK_SCALE, e),
  };
};

const light = scenes.theme === 'light';
const titleColor = light ? '#0f172a' : '#e2e8f0';
const outroColor = light ? '#15803d' : '#34d399';
const shadow = light ? '0 8px 40px rgba(255,255,255,0.35)' : '0 8px 40px rgba(0,0,0,0.8)';

export const StoryVideo: React.FC = () => {
  const frame = useCurrentFrame();
  const cam = cameraAt(frame);
  const duration = scenes.scene_count * scenes.scene_frames;

  const titleOpacity = interpolate(frame, [0, 25, 70, 100], [0, 1, 1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const outroOpacity = interpolate(
    frame,
    [duration - 90, duration - 50],
    [0, 1],
    {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'}
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: light ? '#f1f5f9' : '#0b1220',
        overflow: 'hidden',
      }}
    >
      <style>{`.story-svg svg { width: 100%; height: 100%; display: block; }`}</style>
      <div style={{width: scenes.video_w, height: scenes.video_h, position: 'relative'}}>
        <div
          className="story-svg"
          style={{
            position: 'absolute',
            left: -cam.x * cam.scale * K,
            top: -cam.y * cam.scale * K,
            width: scenes.svg_w * cam.scale * K,
            height: scenes.svg_h * cam.scale * K,
          }}
          dangerouslySetInnerHTML={{__html: storySvg}}
        />
      </div>

      <AbsoluteFill
        style={{justifyContent: 'center', alignItems: 'center', opacity: titleOpacity}}
      >
        <div
          style={{
            color: titleColor,
            fontSize: 110 * K,
            fontWeight: 800,
            letterSpacing: 6,
            fontFamily: 'system-ui, sans-serif',
            textAlign: 'center',
            textShadow: shadow,
          }}
        >
          {scenes.title}
        </div>
      </AbsoluteFill>

      <AbsoluteFill
        style={{justifyContent: 'center', alignItems: 'center', opacity: outroOpacity}}
      >
        <div
          style={{
            color: outroColor,
            fontSize: 130 * K,
            fontWeight: 800,
            letterSpacing: 8,
            fontFamily: 'system-ui, sans-serif',
            textShadow: shadow,
          }}
        >
          {scenes.outro_text ?? 'THE END'}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};